// FuseRRF combines dense and lexical search results using Reciprocal Rank Fusion.
// The formula is: score = sum(1 / (k + rank)) for each result list.
// Parameter k controls the smoothing - larger k reduces the impact of rank differences.
// Default k=60 is commonly used in literature.
// Returns results sorted by fused score in descending order.
func FuseRRF(denseResults, lexicalResults []SearchResult, k int) []SearchResult {
	results, _ := FuseRRFWithError(denseResults, lexicalResults, k)
	return results
}

// HybridSearch performs combined dense (vector) and lexical (FTS5) search.
// Results are fused using Reciprocal Rank Fusion (RRF) for improved recall.
// Returns an error if the storage doesn't support lexical search.
func (s *Searcher) HybridSearch(ctx context.Context, query string, opts HybridSearchOptions) ([]SearchResult, error) {
	if query == "" {
		return nil, errors.New("query cannot be empty")
	}
	if opts.Threshold < 0 || opts.Threshold > 1 {
		return nil, errors.New("threshold must be between 0.0 and 1.0")
	}
	if opts.TopK < 0 {
		return nil, errors.New("topK must be non-negative")
	}

	// Check if storage supports lexical search
	lexicalSearcher, ok := s.storage.(LexicalSearcher)
	if !ok {
		return nil, errors.New("hybrid search requires storage with lexical search support")
	}

	// Set defaults
	k := opts.FusionK
	if k <= 0 {
		k = 60
	}
	alpha := opts.FusionAlpha
	if alpha == 0 {
		alpha = 0.7 // Default when not specified; alpha=0 (lexical-only) is still achievable via explicit negative
	}

	// Perform dense (vector) search
	queryEmbedding, err := s.embedder.Embed(ctx, query)
	if err != nil {
		return nil, err
	}

	denseResults, err := s.storage.Search(ctx, queryEmbedding, opts.SearchOptions)
	if err != nil {
		return nil, err
	}

	// Perform lexical search
	lexicalOpts := LexicalSearchOptions{
		TopK:       opts.TopK,
		Type:       opts.Type,
		PathFilter: opts.PathFilter,
	}
	lexicalResults, err := lexicalSearcher.LexicalSearch(ctx, query, lexicalOpts)
	if err != nil {
		// Log and fall back to dense-only search
		slog.Warn("lexical search failed, falling back to dense-only", "error", err)
		return denseResults, nil
	}

	// Fuse results
	var results []SearchResult
	if opts.UseWeighted {
		results, err = FuseWeighted(denseResults, lexicalResults, alpha)
		if err != nil {
			return nil, err
		}
	} else {
		results = FuseRRF(denseResults, lexicalResults, k)
	}

	// Apply TopK limit
	if opts.TopK > 0 && len(results) > opts.TopK {
		results = results[:opts.TopK]
	}

	// Apply relevance labels
	s.applyRelevanceLabels(ctx, results)

	return results, nil
}

// LexicalSearcher is an optional interface for storage backends that support
// full-text search. Backends implementing this interface can be used with
// hybrid search (dense + lexical fusion).
type LexicalSearcher interface {
	// LexicalSearch performs full-text search using FTS5.
	// Returns results ranked by BM25 relevance score.
	LexicalSearch(ctx context.Context, query string, opts LexicalSearchOptions) ([]SearchResult, error)
}

// TestHybridSearch_FusesDenseAndLexical pins that hybrid search returns the union of the
// dense and lexical hits: a chunk only the FTS5 stage can find still reaches the caller.
func TestHybridSearch_FusesDenseAndLexical(t *testing.T) {
	storage := prefilterFixture(t)
	// Query vector aligns with chunk a only; "lever" is lexical-only and hits chunk b.
	embedder := &tableEmbedder{fallback: []float32{1, 0, 0, 0}}
	searcher := NewSearcher(storage, embedder)

	results, err := searcher.HybridSearch(context.Background(), "lever", HybridSearchOptions{
		SearchOptions: SearchOptions{TopK: 10, Threshold: 0.5},
	})
	if err != nil {
		t.Fatalf("HybridSearch() error = %v", err)
	}

	got := map[string]bool{}
	for _, r := range results {
		got[r.Chunk.ID] = true
	}
	if !got["a"] {
		t.Error("chunk a (the dense hit) is missing from the fused results")
	}
	if !got["b"] {
		t.Error("chunk b (the lexical-only hit for \"lever\") is missing from the fused results")
	}
	if len(results) != 2 {
		t.Errorf("fused results = %v, want exactly a and b", ids(results))
	}
	if results[0].Preview == "" {
		t.Error("hybrid results should carry previews from applyRelevanceLabels")
	}
}

// TestRRFusion_EmptyDense verifies handling when dense search returns no results.
func TestRRFusion_EmptyDense(t *testing.T) {
	denseResults := []SearchResult{} // empty
	lexicalResults := makeTestResults("A", "B", "C")

	results := FuseRRF(denseResults, lexicalResults, 60)

	if len(results) != 3 {
		t.Errorf("expected 3 results from lexical-only, got %d", len(results))
	}

	// Results should be from lexical with adjusted RRF scores
	for i, r := range results {
		if r.Score <= 0 {
			t.Errorf("result %d should have positive score, got %f", i, r.Score)
		}
	}

	// Order should be preserved (A, B, C)
	if results[0].Chunk.ID != "A" {
		t.Errorf("expected A first, got %s", results[0].Chunk.ID)
	}
}

// FuseRRFMemoryWithTopK is FuseRRFMemory with a result count limit.
func FuseRRFMemoryWithTopK(denseResults, lexicalResults []MemorySearchResult, k int, topK int) []MemorySearchResult {
	results := FuseRRFMemory(denseResults, lexicalResults, k)
	if topK > 0 && len(results) > topK {
		results = results[:topK]
	}
	return results
}

// FuseRRFWithTopK combines results using RRF and limits to top K results.
// If topK is 0 or negative, all results are returned.
func FuseRRFWithTopK(denseResults, lexicalResults []SearchResult, k int, topK int) []SearchResult {
	results := FuseRRF(denseResults, lexicalResults, k)
	if topK > 0 && len(results) > topK {
		results = results[:topK]
	}
	return results
}

// TestSafeLexicalSearch_EscapesOperators pins the difference between the raw and the safe
// entry points: a query containing an FTS5 operator character is a syntax error through
// LexicalSearch but is treated as literal text through SafeLexicalSearch.
func TestSafeLexicalSearch_EscapesOperators(t *testing.T) {
	storage := ftsFixture(t)
	ctx := context.Background()

	if _, err := storage.LexicalSearch(ctx, `spinner"`, LexicalSearchOptions{TopK: 5}); err == nil {
		t.Fatal("LexicalSearch() with an unbalanced quote should fail")
	}

	results, err := storage.SafeLexicalSearch(ctx, `spinner"`, LexicalSearchOptions{TopK: 5})
	if err != nil {
		t.Fatalf("SafeLexicalSearch() should escape the quote, got %v", err)
	}
	if len(results) != 1 || results[0].Chunk.ID != "a" {
		t.Errorf("SafeLexicalSearch() = %v, want chunk a", ids(results))
	}
}

// TestHybridSearch_FallsBackOnLexicalError pins that an FTS5 syntax error degrades to
// dense-only results instead of failing the whole search.
func TestHybridSearch_FallsBackOnLexicalError(t *testing.T) {
	storage := prefilterFixture(t)
	searcher := NewSearcher(storage, &tableEmbedder{fallback: []float32{1, 0, 0, 0}})

	results, err := searcher.HybridSearch(context.Background(), `lever"`, HybridSearchOptions{
		SearchOptions: SearchOptions{TopK: 10, Threshold: 0.5},
	})
	if err != nil {
		t.Fatalf("HybridSearch() should swallow the lexical error, got %v", err)
	}
	if len(results) != 1 || results[0].Chunk.ID != "a" {
		t.Errorf("results = %v, want only the dense hit a", ids(results))
	}
}

// HybridSearchMemory performs hybrid search (dense + lexical) on memory entries.
// Requires storage to implement MemoryLexicalSearcher.
func HybridSearchMemory(
	ctx context.Context,
	storage Storage,
	embedder EmbedderInterface,
	query string,
	opts HybridMemorySearchOptions,
) ([]MemorySearchResult, error) {
	if query == "" {
		return nil, errors.New("query cannot be empty")
	}

	// Verify storage supports lexical search
	lexicalSearcher, ok := storage.(MemoryLexicalSearcher)
	if !ok {
		return nil, errors.New("storage does not support lexical memory search")
	}

	// Set defaults
	fusionK := opts.FusionK
	if fusionK <= 0 {
		fusionK = 60
	}
	topK := opts.TopK
	if topK <= 0 {
		topK = 10
	}

	// Over-fetch for better fusion results
	overFetchK := topK * 3
	if overFetchK < 50 {
		overFetchK = 50
	}

	// Generate query embedding
	queryEmbedding, err := embedder.Embed(ctx, query)
	if err != nil {
		return nil, err
	}

	// Dense search
	denseOpts := opts.MemorySearchOptions
	denseOpts.TopK = overFetchK
	denseResults, err := storage.SearchMemory(ctx, queryEmbedding, denseOpts)
	if err != nil {
		return nil, err
	}

	// Lexical search
	lexicalOpts := MemoryLexicalSearchOptions{
		TopK:   overFetchK,
		Tags:   opts.Tags,
		Source: opts.Source,
		Status: opts.Status,
	}
	lexicalResults, err := lexicalSearcher.LexicalSearchMemory(ctx, query, lexicalOpts)
	if err != nil {
		// Degrade gracefully: use dense-only results
		lexicalResults = []MemorySearchResult{}
	}

	// Fuse results
	var results []MemorySearchResult
	if opts.UseWeighted {
		alpha := opts.FusionAlpha
		// Note: alpha=0 is valid (100% lexical) but uncommon.
		// Callers must explicitly set UseWeighted=true to use weighted fusion.
		results, err = FuseWeightedMemory(denseResults, lexicalResults, alpha)
		if err != nil {
			return nil, err
		}
	} else {
		results = FuseRRFMemory(denseResults, lexicalResults, fusionK)
	}

	// Apply temporal decay BEFORE topK so decay can influence final ranking
	if opts.Decay != nil && opts.Decay.Enabled {
		ApplyTemporalDecay(results, *opts.Decay, time.Now())
		sort.Slice(results, func(i, j int) bool {
			return results[i].Score > results[j].Score
		})
	}

	// Apply topK limit after decay
	if topK > 0 && len(results) > topK {
		results = results[:topK]
	}

	return results, nil
}
